impl Solution{pub fn plus_one(head:Option<Box<ListNode>>)->Option<Box<ListNode>>{let mut v=vec![];let mut p=head;while let Some(mut n)=p{v.push(n.val);p=n.next.take();}let mut carry=1;for i in (0..v.len()).rev(){let x=v[i]+carry;v[i]=x%10;carry=x/10;if carry==0{break}}if carry>0{v.insert(0,carry)}let mut r=None;for &x in v.iter().rev(){let mut n=Box::new(ListNode::new(x));n.next=r;r=Some(n)}r}}
